migrations.sql:
CREATE TABLE workspaces (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 100), slug TEXT NOT NULL UNIQUE CHECK(length(slug) BETWEEN 1 AND 80), icon_url TEXT, created_by TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE workspace_members (workspace_id TEXT NOT NULL REFERENCES workspaces(id), user_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','admin','member')), joined_at INTEGER NOT NULL, display_name TEXT NOT NULL DEFAULT '' CHECK(length(display_name) <= 80), avatar_url TEXT, mention_handle TEXT, PRIMARY KEY(workspace_id,user_id));
CREATE TABLE channels (id TEXT PRIMARY KEY NOT NULL, workspace_id TEXT NOT NULL REFERENCES workspaces(id), name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 80), description TEXT NOT NULL DEFAULT '' CHECK(length(description) <= 1000), is_private INTEGER NOT NULL DEFAULT 0 CHECK(is_private IN (0,1)), created_by TEXT NOT NULL, created_at INTEGER NOT NULL, is_archived INTEGER NOT NULL DEFAULT 0 CHECK(is_archived IN (0,1)), topic TEXT NOT NULL DEFAULT '' CHECK(length(topic) <= 250), archived_at INTEGER, UNIQUE(workspace_id,name), UNIQUE(workspace_id,id));
CREATE TABLE channel_members (channel_id TEXT NOT NULL, user_id TEXT NOT NULL, workspace_id TEXT NOT NULL, last_read_at INTEGER, joined_at INTEGER NOT NULL, PRIMARY KEY(channel_id,user_id), FOREIGN KEY(workspace_id,channel_id) REFERENCES channels(workspace_id,id), FOREIGN KEY(workspace_id,user_id) REFERENCES workspace_members(workspace_id,user_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE messages (id TEXT PRIMARY KEY NOT NULL, channel_id TEXT NOT NULL, workspace_id TEXT NOT NULL, user_id TEXT NOT NULL, body TEXT NOT NULL CHECK(length(body) <= 10000), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, is_deleted INTEGER NOT NULL DEFAULT 0 CHECK(is_deleted IN (0,1)), edited_at INTEGER, deleted_at INTEGER, parent_id TEXT REFERENCES messages(id), FOREIGN KEY(workspace_id,channel_id) REFERENCES channels(workspace_id,id), UNIQUE(workspace_id,id));
CREATE TABLE reactions (message_id TEXT NOT NULL, user_id TEXT NOT NULL, emoji TEXT NOT NULL CHECK(length(emoji) BETWEEN 1 AND 32), workspace_id TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(message_id,user_id,emoji), FOREIGN KEY(workspace_id,message_id) REFERENCES messages(workspace_id,id));
CREATE TABLE audit_log (id TEXT PRIMARY KEY NOT NULL, workspace_id TEXT NOT NULL REFERENCES workspaces(id), actor_id TEXT NOT NULL, action TEXT NOT NULL, target_id TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE message_reactions (message_id TEXT NOT NULL, channel_id TEXT NOT NULL, workspace_id TEXT NOT NULL, user_id TEXT NOT NULL, emoji TEXT NOT NULL CHECK(length(emoji) BETWEEN 1 AND 32), created_at INTEGER NOT NULL, PRIMARY KEY(message_id,user_id,emoji), FOREIGN KEY(workspace_id,channel_id,message_id) REFERENCES messages(workspace_id,channel_id,id));
CREATE TABLE activity_log (id TEXT PRIMARY KEY NOT NULL, workspace_id TEXT NOT NULL REFERENCES workspaces(id), actor_id TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, action TEXT NOT NULL, changes TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL);
CREATE TABLE mentions (message_id TEXT NOT NULL,workspace_id TEXT NOT NULL,channel_id TEXT NOT NULL,user_id TEXT NOT NULL,created_at INTEGER NOT NULL,seen_at INTEGER,PRIMARY KEY(message_id,user_id),FOREIGN KEY(workspace_id,channel_id,message_id) REFERENCES messages(workspace_id,channel_id,id),FOREIGN KEY(workspace_id,channel_id,user_id) REFERENCES channel_members(workspace_id,channel_id,user_id) DEFERRABLE INITIALLY DEFERRED);
CREATE UNIQUE INDEX one_owner ON workspace_members(workspace_id) WHERE role = 'owner';
CREATE INDEX member_workspaces ON workspace_members(user_id,workspace_id);
CREATE INDEX message_timeline ON messages(workspace_id,channel_id,created_at DESC,id DESC);
CREATE INDEX audit_workspace ON audit_log(workspace_id,created_at DESC);
CREATE UNIQUE INDEX message_channel_scope ON messages(workspace_id,channel_id,id);
CREATE INDEX activity_workspace ON activity_log(workspace_id,created_at DESC);
CREATE INDEX activity_entity ON activity_log(workspace_id,entity_type,entity_id,created_at DESC);
CREATE INDEX thread_replies ON messages(workspace_id,channel_id,parent_id,created_at DESC,id DESC);
CREATE UNIQUE INDEX member_mention_handle ON workspace_members(workspace_id,mention_handle);
CREATE UNIQUE INDEX channel_member_scope ON channel_members(workspace_id,channel_id,user_id);
CREATE INDEX mentions_inbox ON mentions(workspace_id,user_id,created_at DESC,message_id DESC);
